function parseDeepSeek(item) {
  const j = item.json || {};

  const content =
    j?.choices?.[0]?.message?.content ??
    j?.message?.content ??
    j?.content ??
    '{}';

  if (typeof content === 'object' && content !== null) {
    return content;
  }

  let text = String(content || '').trim();

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    return JSON.parse(text);
  } catch (e) {
    const match = text.match(/\{[\s\S]*\}/);
    if (!match) return null;

    try {
      return JSON.parse(match[0]);
    } catch (e2) {
      return null;
    }
  }
}

function normalizeCountry(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
