  const reasons = [];

  const dive =
    /(scuba|diving|dive|dives|padi|ssi|cmas|bsac|raid|plongée|plongee|tauchen|tauchschule|tauchzentrum|tauchreise|duiken|duik)/i;

  const travel =
    /(liveaboard|safari|dive safari|tauchsafari|cruise|croisière|croisiere|red sea|egypt|maldives|maldivian|dive trip|diving trip|dive travel|scuba travel|holiday|holidays|voyage|reise|reisen|tour|tours|expedition|boat trip|yacht|charter|group trip)/i;

  const commercial =
    /(scuba tour agency|tour agency|tour operator|travel agent|travel agency|reisebüro|cruise agency|boat tour agency|dmc|destination management|mice|incentive travel|corporate retreat)/i;

  const bad =
    /(swim school|schwimmschule|skydiving|fallschirm|data science|education center|technologisches institut|outdoor sports store|bicycle shop|shoe shop|software|restaurant|hotel only|real estate)/i;

  const hasDive = has(dive, text);
  const hasTravel = has(travel, text);
  const hasCommercial = has(commercial, text);
  const hasBad = has(bad, text);

  if (hasDive) {
    score += 10;
    reasons.push('dive');
  }

  if (hasTravel) {
    score += 15;
    reasons.push('travel');
  }

  if (hasCommercial) {
    score += 10;
    reasons.push('commercial_travel');
  }

  if (hasBad) {
    score -= 30;
    reasons.push('bad_category');
  }

  const pass =
    !hasBad &&
    (
      (hasDive && hasTravel) ||
      (hasDive && hasCommercial) ||
      (hasCommercial && /(maldives|liveaboard|yacht|charter|cruise|incentive|retreat)/i.test(text))
    );

  return {
    score,
    pass,
    reasons,
    hasDive,
    hasTravel,
    hasCommercial,
    hasBad
  };
}

const out = [];

for (const item of items) {
  const j = item.json || {};
  const gate = scoreLead(j);

  if (!gate.pass) continue;

  out.push({
    json: {
      ...j,
      homepage_evidence_gate: gate
    }
  });
}

out.sort((a, b) => {
  return Number(b.json.homepage_evidence_gate.score || 0) -
    Number(a.json.homepage_evidence_gate.score || 0);
});

return out.slice(0, MAX_DEEPSEEK_PREQUAL_PER_RUN);

function canonicalDomain(value) {
  if (!value) return '';

  let s = String(value).trim().toLowerCase();

  s = s.replace(/^['"]|['"]$/g, '').trim();
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//i, '');
  s = s.replace(/^\/\//, '');
  s = s.replace(/^.*@/, '');
  s = s.split(/[/?#]/)[0];
  s = s.replace(/:\d+$/, '');
  s = s.replace(/^www\./, '').replace(/\.$/, '').trim();

  if (!s || !s.includes('.')) return '';
  if (!/^[a-z0-9.-]+$/.test(s)) return '';

  return s;
}

// Logs a lightweight prospect doc for EVERY company Outscraper/Maps
// returned this run (after dedupe/country filter), regardless of
// whether it ever gets crawled or passes any later gate. This is the
// permanent record of "we discovered this" so nothing found by a
// Google Maps query is ever silently lost, even if the crawl budget
// cap means it doesn't get researched this run.
const seen = new Set();
const candidates = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const domain = canonicalDomain(j.domain || j.website);

  if (!domain) continue;
  if (seen.has(domain)) continue;
  seen.add(domain);

  candidates.push({
    _id: `prospect:${domain}`,
    domain,
    company_name: j.company_name || '',
    website: j.website || '',
    source: j.source || j.discovery_source || '',
    discovery_query: j.discovery_query || j.source_query || '',
    target_country: j.target_country || j.business_country || '',
    category: j.category || j.maps_type || '',
    phone: j.phone || '',
    place_id: j.place_id || '',
    rating: j.rating ?? null,
    reviews: j.reviews ?? null,
    run_id: j.run_id || ''
  });
}

return [{
  json: {
    keys: candidates.map(c => c._id),
    candidates
  }
}];

const source = $('Build Prospect Docs').first().json;
const rows = $json.rows || $json.body?.rows || [];
const existingById = new Map();

for (const row of rows) {
  if (row?.doc && !row.error) {
    existingById.set(row.id, row.doc);
  }
}

const now = new Date().toISOString();
const docs = [];

for (const incoming of (source.candidates || [])) {
  const existing = existingById.get(incoming._id);

  const doc = {
    ...(existing || {}),
    ...incoming,

    type: 'prospect',
    first_seen_at: existing?.first_seen_at || now,
    last_seen_at: now,
    times_seen: Number(existing?.times_seen || 0) + 1
  };

  if (existing?._rev) {
    doc._rev = existing._rev;
  }

  docs.push(doc);
}

return [{
  json: {
    prospect_docs: docs,
    prospect_count: docs.length
  }
}];

// NOTE: sheetId below is a PLACEHOLDER (999999999).
// Create a second tab in the same spreadsheet (e.g. "Manual Review"),
// open it in the browser, copy the gid= number from the URL, and
// replace 999999999 with that number before running this workflow.
const row = [
  $json.company_name,
  $json.website,
  $json.domain,
  $json.country,
  $json.priority,
  $json.persona,
  $json.icp_score,
  $json.intent_score,
  $json.contact_channel,
  $json.contact_value,
  $json.phone,
  $json.instagram_url,
  $json.personalized_first_line,
  $json.reason,
  $json.outreach_eligibility,
  $json.hold_reason,
  $json.crm_company_id,
  $json.run_id
];

const values = row.map(value => ({
  userEnteredValue: {
    stringValue: String(value ?? '')
  }
}));

return {
  json: {
    ...$json,
    manual_review_batch_update_body: {
      requests: [
        {
          appendCells: {
            sheetId: Number($env.GOOGLE_SHEET_MANUAL_GID || 0),
            rows: [
              { values }
            ],
            fields: 'userEnteredValue'
          }
        }
      ]
    }
  }
};
